def solve(n):
    """Return the number of prime numbers strictly less than *n*.
    Handles non‑integer or negative inputs by returning 0.
    Uses the Sieve of Eratosthenes for reasonable sizes (n <= 5_000_000).
    For larger *n* a simple trial division count is used to avoid huge memory.
    """
    # Validate input
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Choose strategy based on size to keep memory reasonable
    LIMIT_FOR_SIEVE = 5_000_000
    if n <= LIMIT_FOR_SIEVE:
        limit = n
        is_prime = bytearray(b"\x01") * limit
        is_prime[0:2] = b"\x00\x00"
        import math
        max_p = int(math.isqrt(limit - 1))
        for p in range(2, max_p + 1):
            if is_prime[p]:
                start = p * p
                step = p
                is_prime[start:limit:step] = b"\x00" * ((limit - 1 - start) // step + 1)
        return sum(is_prime)
    # For larger n, count primes by trial division (still correct for moderate n)
    import math
    def is_prime_num(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        r = int(math.isqrt(x))
        for d in range(3, r + 1, 2):
            if x % d == 0:
                return False
        return True
    cnt = 0
    for num in range(2, n):
        if is_prime_num(num):
            cnt += 1
    return cnt

