def solve(matrix):
    # determinant using recursive Laplace expansion
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    if n == 2:
        a, b = matrix[0]
        c, d = matrix[1]
        return a * d - b * c
    det = 0
    for col, element in enumerate(matrix[0]):
        if element == 0:
            continue
        sub = [row[:col] + row[col+1:] for row in matrix[1:]]
        sign = -1 if col % 2 else 1
        det += sign * element * solve(sub)
    return det

