def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    coins from the list `coins`. If impossible, return -1.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values and deduplicate
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    # Initialize DP array; use amount+1 as a sentinel for INF
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

