def solve(matrix: list) -> int:
    """Return the determinant of a square integer matrix, exactly, as an int.

    Uses the Bareiss fraction-free elimination: every intermediate value is
    an exact minor of the original matrix, so integer division never loses
    precision. Row swaps flip the sign; an empty matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    M = [row[:] for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if M[k][k] == 0:
            for r in range(k + 1, n):
                if M[r][k] != 0:
                    M[k], M[r] = M[r], M[k]
                    sign = -sign
                    break
            else:
                return 0
        pivot = M[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                M[i][j] = (M[i][j] * pivot - M[i][k] * M[k][j]) // prev
            M[i][k] = 0
        prev = pivot
    return sign * M[n - 1][n - 1]

def solve(n, edges):
    import heapq
    # Build graph
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if a<0 or a>=n or b<0 or b>=n:
            continue
        adj[a].append(b)
        indeg[b]+=1
    heap = [i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heapq.heappush(heap, v)
    if len(order)!=n:
        return []
    return order

